using System;
using System.Linq;
using System.Reflection;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Game;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    const string FreshSoloDay="20411020";
    static string FreshSoloSnapshot(GameState p,GameState[] players,GameState peer){return Convert.ToString(Sql("SELECT json_build_object('prior',@prior::json,'arena',(SELECT json_agg(r ORDER BY entityid) FROM arena r WHERE entityid=ANY(@uids)),'teamarena',(SELECT json_agg(r ORDER BY entityid) FROM teamarena r WHERE entityid=ANY(@uids)),'matches',(SELECT json_agg(r ORDER BY id) FROM revora_arena_matches r WHERE id=ANY((SELECT runs FROM revora_fresh_solo_probe)::uuid[])),'statistics',(SELECT json_agg(r ORDER BY run,uid) FROM revora_arena_result_statistics r WHERE run=ANY((SELECT runs FROM revora_fresh_solo_probe)::uuid[])),'entries',(SELECT json_agg(r ORDER BY uid,run) FROM revora_arena_daily_entries r WHERE day=@day AND uid=ANY(@uids)),'rank',(SELECT json_agg(r ORDER BY uid) FROM revora_arena_rank_rewards r WHERE day=@day))::text","prior",FreshCoupleSnapshot(p,players,peer),"uids",players.Concat(new[]{peer}).Select(w=>(long)w.Entity.UID).ToArray(),"day",FreshSoloDay));}
    static void FreshSoloSave(GameState p,GameState[] players,GameState peer,int stage){foreach(var who in players.Concat(new[]{peer}))Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_solo_probe SET stage=@stage,snapshot=@snapshot","stage",stage,"snapshot",FreshSoloSnapshot(p,players,peer));}
    static void FreshSoloJourney(string phase){
        var p=FreshLoadSaved(true,true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();Server.GamePool=players;Call(typeof(Revora.Database.JiangHu),"LoadClient",p);Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w)) && p.Entity.Class==25);


        var peer=FreshContributor(Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_warrior_peer_probe WHERE done")),"FreshWar1");Server.GamePool=players.Concat(new[]{peer}).ToArray();Require(!peer.Fake && peer.Account.State==AccountTable.AccountState.Player && peer.Entity.Class==20 && peer.Entity.Level>=130 && p.Entity.Level>=130);


        var opponents=new[]{peer,players[0],players[2]};DateTime now=new DateTime(2041,10,20,18,0,0,DateTimeKind.Utc);Require(opponents.All(w=>w.Entity.Level>=70 && !w.Entity.Dead));
        if((bool)Sql("SELECT to_regclass('revora_fresh_solo_probe') IS NULL")){Require(phase.EndsWith("fight") && FreshCoupleSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_couple_probe WHERE step=4")));Sql("CREATE TABLE revora_fresh_solo_probe(stage int,runs uuid[],hits int,snapshot text);INSERT INTO revora_fresh_solo_probe VALUES(0,ARRAY[]::uuid[],0,NULL)");FreshSoloSave(p,players,peer,0);}
        if(phase.EndsWith("inspect")){System.IO.File.WriteAllText("fresh-solo-saved.json",Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_solo_probe")));System.IO.File.WriteAllText("fresh-solo-current.json",FreshSoloSnapshot(p,players,peer));foreach(var who in new[]{p}.Concat(opponents))System.Console.WriteLine("[fresh-solo-inspect] uid="+who.Entity.UID+" points="+who.ArenaStatistic.ArenaPoints+" status="+who.ArenaStatistic.Status+" team="+who.TeamArenaStatistic.Status+" dead="+who.Entity.Dead);System.Console.WriteLine("[fresh-solo-inspect] matches="+Sql("SELECT count(*) FROM revora_arena_matches WHERE day=@day","day",FreshSoloDay));System.Console.WriteLine("[career-process] "+phase+"-passed");System.Console.Out.Flush();Environment.Exit(0);return;}
        Require(FreshSoloSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_solo_probe")));int stage=(int)Sql("SELECT stage FROM revora_fresh_solo_probe");Feature("ArenaMatchLedger").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        if(phase.EndsWith("fight")){
            Require(stage==0);var runs=((Guid[])Sql("SELECT runs FROM revora_fresh_solo_probe")).ToList();int hits=(int)Sql("SELECT hits FROM revora_fresh_solo_probe");Action<GameState,uint,uint> request=(who,dialog,button)=>{var frame=new Qualifier.ArenaSignup{DialogID=dialog,OptionID=button}.BuildPacket();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);Revora.Network.PacketHandler.HandlePacket(frame,who);Require(who.Action==2);};
            while(runs.Count<20){var target=opponents[runs.Count%3];now=new DateTime(2041,10,20,18,0,0,DateTimeKind.Utc).AddMinutes(runs.Count*2);Require(!target.Entity.Dead && !p.Entity.Dead);p.Entity.Teleport(1002,408,330);target.Entity.Teleport(1002,410,330);request(p,0,0);request(target,0,0);Require((Qualifier.PlayerList.ContainsKey(p.Entity.UID) && Qualifier.PlayerList.ContainsKey(target.Entity.UID)) || ReferenceEquals(p.ArenaStatistic.PlayWith,target));
                Qualifier.EngagePlayers();Require(ReferenceEquals(p.ArenaStatistic.PlayWith,target));
                request(p,3,1);request(target,3,1);Qualifier.VerifyAwaitingPeople();var group=p.QualifierGroup;
                Require(group!=null && ReferenceEquals(target.QualifierGroup,group) && p.Map.BaseID==700 && p.Entity.MapID==target.Entity.MapID);Guid run=(Guid)group.GetType().GetField("ParticipationKey",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(group);
                group.ImportTime=group.CreateTime=Time32.Now.AddSeconds(-13);p.Attackable=target.Attackable=true;p.CantAttack=target.CantAttack=Time32.Now.AddSeconds(-1);int count=0;while(!group.Done && count<100){p.Entity.X=target.Entity.X;p.Entity.Y=(ushort)(target.Entity.Y+1);p.Screen.Add(target.Entity);target.Screen.Add(p.Entity);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.Entity.UID,X=target.Entity.X,Y=target.Entity.Y,AttackType=Attack.Melee},p);count++;}Require(group.Done);now=now.AddSeconds(20);group.DoneStamp=Time32.Now.AddSeconds(-5);Qualifier.CheckGroups();Require((long)Sql("SELECT count(*) FROM revora_arena_matches WHERE id=@run AND state='finished' AND winner=@uid AND day=@day","run",run,"uid",(long)p.Entity.UID,"day",FreshSoloDay)==1);
                // Complete the documented controlled town return before saving the checkpoint.
                p.Entity.Teleport(1002,408,330);target.Entity.Teleport(1002,410,330);if(target.Entity.Dead){target.Entity.DeathStamp=Time32.Now.AddSeconds(-20);GeneralData.Revive(new Data(true){UID=target.Entity.UID,ID=Data.Revive},target);}Require(!target.Entity.Dead);runs.Add(run);hits+=count;Sql("UPDATE revora_fresh_solo_probe SET runs=@runs,hits=@hits","runs",runs.ToArray(),"hits",hits);FreshSoloSave(p,players,peer,runs.Count==20?1:0);
            }
        }else if(phase.EndsWith("pay")){
            Require(stage==1);now=now.AddDays(1);var ranking=Feature("ArenaRankingSettlement");Call(ranking,"Close",FreshSoloDay);foreach(var who in new[]{p}.Concat(opponents)){uint before=who.CurrentHonor;uint award=Convert.ToUInt32(Sql("SELECT honor FROM revora_arena_rank_rewards WHERE day=@day AND uid=@uid AND paid_at IS NULL","day",FreshSoloDay,"uid",(long)who.Entity.UID));Require(award>0);Call(ranking,"Pay",who);Require(who.CurrentHonor==before+award && who.TeamArenaStatistic.CurrentHonor==who.CurrentHonor);string paid=FreshSoloSnapshot(p,players,peer);Call(ranking,"Pay",who);Require(paid==FreshSoloSnapshot(p,players,peer));System.Console.WriteLine("[fresh-solo] uid="+who.Entity.UID+" rank-honor="+award);}FreshSoloSave(p,players,peer,2);
        }else {Require(phase.EndsWith("reload") && stage==2);string saved=FreshSoloSnapshot(p,players,peer);foreach(var who in new[]{p}.Concat(opponents)){Require(who.CurrentHonor==who.TeamArenaStatistic.CurrentHonor);Call(Feature("ArenaRankingSettlement"),"Pay",who);}Require(saved==FreshSoloSnapshot(p,players,peer));}
        Require((long)Sql("SELECT count(*) FROM revora_arena_matches WHERE id=ANY((SELECT runs FROM revora_fresh_solo_probe)::uuid[]) AND winner=@uid AND state='finished'","uid",(long)p.Entity.UID)==20 && (long)Sql("SELECT count(*) FROM revora_achievement_evidence WHERE uid=@uid AND achievement_id IN(11102,11105,11107,11111,11112)","uid",(long)p.Entity.UID)==5 && FreshSoloSnapshot(p,players,peer)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_solo_probe")));System.Console.WriteLine("[career-process] "+phase+"-passed hits="+Sql("SELECT hits FROM revora_fresh_solo_probe"));System.Console.Out.Flush();Environment.Exit(0);
    }
}
